def parse(msid) do
  case String.split(msid, " ") do
    [""] ->
      {:error, :invalid_msid}

    ["", _app_data] ->
      {:error, :invalid_msid}

    [id] ->
      {:ok, %__MODULE__{id: id}}

    [id, app_data] ->
      msid = %__MODULE__{id: id, app_data: app_data}
      {:ok, msid}

    _invalid_msid ->
      {:error, :invalid_msid}
  end
end

def parse(ssrc) do
  with [id, attribute] <- String.split(ssrc, " ", parts: 2),
       {:ok, id} <- Utils.parse_numeric_string(id) do
    case String.split(attribute, ":", parts: 2) do
      [attribute, value] -> {:ok, %__MODULE__{id: id, attribute: attribute, value: value}}
      [attribute] -> {:ok, %__MODULE__{id: id, attribute: attribute}}
      _invalid_ssrc -> {:error, :invalid_ssrc}
    end
  else
    _invalid_ssrc -> {:error, :invalid_ssrc}
  end
end

def parse(ssrc_group) do
  with [semantics | ssrc_ids] when ssrc_ids != [] <- String.split(ssrc_group, " "),
       {:ok, ssrcs} <- Bunch.Enum.try_map(ssrc_ids, &Utils.parse_numeric_string/1) do
    {:ok, %__MODULE__{semantics: semantics, ssrcs: ssrcs}}
  else
    [_invalid] -> {:error, :invalid_ssrc_group}
    _invalid_ssrc -> {:error, :invalid_ssrc}
  end
end

def parse(bandwidth) do
  with [type, bandwidth] <- String.split(bandwidth, ":"),
       {:ok, bandwidth} <- parse_bandwidth(bandwidth),
       {:ok, type} <- parse_type(type) do
    bandwidth = %__MODULE__{type: type, bandwidth: bandwidth}
    {:ok, bandwidth}
  else
    _invalid_bandwidth -> {:error, :invalid_bandwidth}
  end
end

